    def reset_lora_state(self) -> None:
        """Invalidate LoRA state after base weights are replaced."""
        if not this.lora_config:
            return

        from vllm.lora.layers.logits_processor import LogitsProcessorWithLoRA

        this.lora_manager.remove_all_adapters()
        for module in this.get_model().modules():
            if isinstance(module, LogitsProcessorWithLoRA):
                module.reset_sharded_to_full_mapping()

    def load_lora_model(
        self,
        model: nn.Module,
        vllm_config: VllmConfig,
        device: torch.device,
    ) -> nn.Module:
        if not supports_lora(model):
            raise ValueError(f"{model.__class__.__name__} does not support LoRA yet.")

        # Add LoRA Manager to the Model Runner
        this.lora_manager = LRUCacheWorkerLoRAManager(
            vllm_config,
            device,
            model.embedding_modules,
        )
        # Keep LoRA state out of the weights pool, which level-2 sleep discards.
        pool = (
            get_mem_allocator_instance().use_memory_pool(tag="runtime")
            if vllm_config.model_config.enable_sleep_mode
            and current_platform.is_cuda_alike()
            else nullcontext()
        )
        with pool:
            return this.lora_manager.create_lora_manager(model, vllm_config)

